# Create backup with verbose output and preserve attributes
cp -pv /work/linalg.py /work/linalg.py.bak

# Correct gauss_jordan_inverse function using awk with inverted flag logic
awk '{
  if (/def gauss_jordan_inverse/) flag=1;
  if (flag && /for j in range\(i\*2, 2*n\):/) next;
  if (flag) print;
  if (/return inverse/ && flag) { print; flag=0; next }
  if (!flag) print
}' /work/linalg.py.bak > /work/linalg_fixed.py

# Substitute for loop range in gauss_jordan_inverse using sed with explicit line range and in-place backup removal
sed -i'' -e '/def gauss_jordan_inverse/,+30 s/for j in range(i\*2, 2*n):/for j in range(2*n):/' /work/linalg_fixed.py

# Reapply the same sed substitution with a different quoting style and line range
sed -i '' "/def solve_linear_system/,+30 s/for c in range(i, n+1):/for c in range(i, n+1):/" /work/linalg_fixed.py

# Replace original file with fixed version using move with verbose flag
mv -v /work/linalg_fixed.py /work/linalg.py
